import 'package:cloud_firestore/cloud_firestore.dart';
class PestObservation{final String id,crop,pest,symptoms,severity,action;final DateTime? createdAt;const PestObservation({required this.id,required this.crop,required this.pest,required this.symptoms,required this.severity,required this.action,required this.createdAt});factory PestObservation.fromDoc(DocumentSnapshot<Map<String,dynamic>>d){final x=d.data()??const{};return PestObservation(id:d.id,crop:(x['crop']??'').toString(),pest:(x['pest']??'').toString(),symptoms:(x['symptoms']??'').toString(),severity:(x['severity']??'medium').toString(),action:(x['action']??'').toString(),createdAt:(x['createdAt']as Timestamp?)?.toDate());}}
class PestMonitoringService{
 final FirebaseFirestore db; PestMonitoringService({FirebaseFirestore?firestore}):db=firestore??FirebaseFirestore.instance;
 PestObservation create({required String crop,required String pest,required String symptoms,required String severity})=>PestObservation(id:'',crop:crop.trim(),pest:pest.trim(),symptoms:symptoms.trim(),severity:severity,action:severity=='high'?'اعزل البؤرة، وثّقها بالصور واطلب مختصاً سريعاً.':'راقب البؤرة وسجّل الانتشار قبل اختيار أي معالجة.',createdAt:null);
 Future<String> save({required String uid,required PestObservation observation})async{final r=db.collection('users').doc(uid).collection('agricultureNotes').doc();await r.set({'title':'Pest Monitoring • '+observation.crop,'note':'الآفة: '+observation.pest+'\nالأعراض: '+observation.symptoms+'\nالشدة: '+observation.severity+'\n'+observation.action,'type':'field','createdAt':FieldValue.serverTimestamp(),'updatedAt':FieldValue.serverTimestamp()});return r.id;}
 Stream<List<PestObservation>> watch({required String uid})=>db.collection('users').doc(uid).collection('agricultureNotes').where('type',isEqualTo:'field').limit(100).snapshots().map((s)=>s.docs.where((d)=>(d.data()['title']??'').toString().startsWith('Pest Monitoring •')).map(PestObservation.fromDoc).toList());
}